import pandas as pd,numpy as np
from scipy.optimize import least_squares
files=['train/A_vref_op1.csv','train/A_vref_op3.csv','train/A_amb_op1.csv','train/A_amb_op2.csv','train/A_load_op2.csv','train/A_gentrip_op1.csv','train/A_fault_op1.csv','train/A_line_op3.csv']
D={f:pd.read_csv(f) for f in files}
def simP(p,d,dt=0.001):
    Kd,tw,tp,Kpv=p
    V=d.voltage_pu.values; th=d.bus_angle_rad.values
    V0=V[0]; P0=d.active_power_pu.values[0]
    n=len(V); P=np.empty(n); pz=P0; y=th[0]
    for i in range(n):
        P[i]=pz
        Pss=P0+Kd*(th[i]-y)/tw+Kpv*(V[i]-V0)
        pz+=dt*(Pss-pz)/tp
        y+=dt*(th[i]-y)/tw
    return P
def res(p,fs):
    return np.concatenate([simP(p,D[f])-D[f].active_power_pu.values for f in fs])
for fs in [files[:2],files]:
    r=least_squares(res,[0.1,0.05,0.2,0.5],args=(fs,),bounds=([-50,0.005,0.005,-50],[50,2,20,50]),max_nfev=60)
    print(np.round(r.x,4), np.std(r.fun))
for f in files: print(f, round(np.std(simP(r.x,D[f])-D[f].active_power_pu.values),4))

