import pandas as pd,numpy as np
from scipy.optimize import least_squares
files=['train/A_vref_op1.csv','train/A_vref_op3.csv','train/A_amb_op1.csv','train/A_amb_op2.csv','train/A_load_op2.csv','train/A_gentrip_op1.csv','train/A_fault_op1.csv','train/A_line_op3.csv']
D={f:pd.read_csv(f) for f in files}
def simQ(p,d,dt=0.001):
    Kq,Kd,tq,Ki,tv=p
    V=d.voltage_pu.values; S=d.voltage_setpoint_pu.values
    V0=V[0]; Vs0=S[0]; Q0=d.reactive_power_pu.values[0]
    n=len(V); Q=np.empty(n); qs=0.0; x=0.0; vf=V0
    for i in range(n):
        Q[i]=Q0+qs-Kd*(vf-V0)+x
        qs+=dt*(Kq*(S[i]-Vs0)-qs)/tq
        x+=dt*Ki*(S[i]-vf)
        vf+=dt*(V[i]-vf)/tv
    return Q
def res(p,fs):
    return np.concatenate([simQ(p,D[f])-D[f].reactive_power_pu.values for f in fs])
r=least_squares(res,[2.0,1.5,0.5,0.1,0.01],args=(files,),bounds=([0,-50,0.01,0,0.001],[50,50,20,50,5]),max_nfev=60)
print(list(np.round(r.x,4)), np.std(r.fun))
for f in files: print(f, round(np.std(simQ(r.x,D[f])-D[f].reactive_power_pu.values),4))

